import json,urllib.request
base='http://127.0.0.1:17448'
out={}
for name,path in [('cutover','/api/projects/control-plane/cutover-r42/status'),('lifecycle','/api/operator-lifecycle')]:
 try:
  out[name]=json.loads(urllib.request.urlopen(base+path,timeout=8).read().decode('utf-8'))
 except Exception as e:
  out[name]={'error':type(e).__name__+': '+str(e)}
print(json.dumps(out,ensure_ascii=True,separators=(',',':')))
